sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
      var cspListQuery = api.state.listQuery;
      var cspListTitle = api.state.listTitle;

    var qry, title;

    var qm = cspListQuery.match(/\^u_request_type=([a-z]+)/i);
      if (event.payload.value=='all') {
        qry = (qm==null || qm.length<2 ? cspListQuery : cspListQuery.replace(qm[0], '')); 
      } else {
        qry = (
            qm==null || qm.length<2 ? 
            cspListQuery + '^u_request_type=' + event.payload.value : 
            cspListQuery.replace(qm[1], event.payload.value)
        );
      }

      var tm = cspListTitle.match(/\s*-\s*[a-z]+$/i);
      if (tm==null || tm.length==0 ) {
        title = cspListTitle + ' - ' + event.payload.value;
      } else {
        title = cspListTitle.replace(tm[0], ' - ' + event.payload.value);
      }

      console.log(qry);
      console.log(title);

      api.setState('listQuery', qry);
      api.setState('listTitle', title);
}
